CAM=('https://dictionary.cambridge.org/grammar/british-grammar/words-sentences-and-clauses','Cambridge English Grammar Today: words, sentences and clauses')
NOUN=('https://dictionary.cambridge.org/grammar/british-grammar/nouns-types-of-nouns','Cambridge English Grammar Today: nouns')
IPA=('https://downloads.bbc.co.uk/worldservice/learningenglish/pronunciation/pdf/sounds/sounds_chart.pdf','BBC Learning English: Sounds of English chart')
